#!/usr/bin/env bash
# Verify Phase 2: the SF=5 staging area generated by DIGen.
#
#   bash scripts/verify-phase-02.sh [volume]       default: tpcdi-staging-sf5
#
# Read-only.  Every check runs inside a container against the volume, so no
# result depends on the host having any particular tool.  Exits non-zero if
# any check fails.
set -u
VOL="${1:-tpcdi-staging-sf5}"
PASS=0; FAIL=0
ok()   { printf '  \033[32mPASS\033[0m  %s\n' "$1"; PASS=$((PASS+1)); }
bad()  { printf '  \033[31mFAIL\033[0m  %s\n' "$1"; FAIL=$((FAIL+1)); }
inv()  { docker run --rm -v "$VOL":/staging alpine:3 sh -c "$1" 2>/dev/null; }

echo "Phase 2 verification -- volume: $VOL"
echo

if ! docker volume inspect "$VOL" >/dev/null 2>&1; then
  echo "  volume '$VOL' does not exist.  Generate it first:"
  echo "    docker volume create $VOL"
  echo "    ( printf '\\nYES\\n'; sleep 120 ) | docker run --rm -i \\"
  echo "        -v $VOL:/staging tpcdi-digen:jre8 -o /staging/sf5 -sf 5"
  exit 1
fi

echo "V1/V3  generator report"
REPORT=$(inv 'cat /staging/sf5/digen_report.txt')
[ -n "$REPORT" ] && ok "digen_report.txt present" || bad "digen_report.txt missing"
echo "$REPORT" | grep -q "Scale Factor: 5" && ok "scale factor 5" || bad "scale factor not 5"
echo "$REPORT" | grep -q "End Time:"        && ok "run finished (End Time written)" || bad "no End Time -- generation aborted"
for B in "Batch1: 7804509" "Batch2: 33380" "Batch3: 33455"; do
  echo "$REPORT" | grep -q "$B" && ok "rows $B" || bad "rows $B  -- got: $(echo "$REPORT" | grep -o "${B%%:*}: [0-9]*")"
done

echo
echo "V2/V8  layout and size"
for B in Batch1 Batch2 Batch3; do
  [ "$(inv "[ -d /staging/sf5/$B ] && echo y")" = y ] && ok "$B present" || bad "$B missing"
done
FW=$(inv 'ls /staging/sf5/Batch1/FINWIRE[0-9]* | grep -vc audit')
[ "$FW" = 203 ] && ok "203 FINWIRE files" || bad "FINWIRE files: $FW (expected 203)"
echo "        size on disk: $(inv 'du -sh /staging/sf5 | cut -f1')"

echo
echo "V4     file inventory (Clauses 2.2.2.1-2.2.2.20)"
MISS=$(inv '
cd /staging/sf5
for f in BatchDate.txt CashTransaction.txt CustomerMgmt.xml DailyMarket.txt \
         Date.txt HR.csv HoldingHistory.txt Industry.txt Prospect.csv \
         StatusType.txt TaxRate.txt Time.txt Trade.txt TradeHistory.txt \
         TradeType.txt WatchHistory.txt; do
  [ -f "Batch1/$f" ] || echo "Batch1/$f"; done
for b in Batch2 Batch3; do
  for f in Account.txt BatchDate.txt CashTransaction.txt Customer.txt \
           DailyMarket.txt HoldingHistory.txt Prospect.csv Trade.txt \
           WatchHistory.txt; do
    [ -f "$b/$f" ] || echo "$b/$f"; done; done')
[ -z "$MISS" ] && ok "every expected file present" || bad "missing: $(echo "$MISS" | tr '\n' ' ')"

echo
echo "V5     CDC columns (Clause 1.3.2)"
B1=$(inv 'head -1 /staging/sf5/Batch1/Trade.txt | cut -d"|" -f1')
case "$B1" in [IUD]) bad "Batch1 has a CDC flag ($B1) -- it must not";; *) ok "Batch1 has no CDC flag";; esac
for B in Batch2 Batch3; do
  F=$(inv "head -1 /staging/sf5/$B/Trade.txt | cut -d'|' -f1")
  case "$F" in [IUD]) ok "$B CDC flag present ($F)";; *) bad "$B CDC flag missing (got '$F')";; esac
done

echo
echo "V6     FINWIRE record types at column 16 (Clause 2.2.2.8)"
TYPES=$(inv 'cat /staging/sf5/Batch1/FINWIRE[0-9]*[0-9] | cut -c16-18 | sort | uniq -c')
echo "$TYPES" | sed 's/^/        /'
N=$(echo "$TYPES" | grep -c .)
[ "$N" = 3 ] && ok "every record classifies as CMP/SEC/FIN" \
             || bad "$N distinct types -- some records do not classify"

echo
echo "V7     audit coverage (what tpcdi_audit.sql reads)"
DS=$(inv 'cd /staging/sf5; find . -name "*_audit.csv" -exec sh -c "tail -n +2 \"\$1\" | cut -d, -f1" _ {} \; | sort -u | tr "\n" " "')
echo "        data sets: $DS"
NDS=$(echo "$DS" | wc -w | tr -d ' ')
[ "$NDS" = 14 ] && ok "14 audit data sets" || bad "$NDS audit data sets (expected 14)"
echo "$DS" | grep -q FactCashBalances \
  && bad "FactCashBalances present -- the audit query expects it absent" \
  || ok "FactCashBalances absent, as the audit query expects"

echo
printf 'passed %d, failed %d\n' "$PASS" "$FAIL"
[ "$FAIL" -eq 0 ] || exit 1
